// Our Noise code checked against vectors from implementations that are not ours: the published
// cacophony vector for this exact protocol, and a fresh batch generated by the Python `noise`
// library on every run. Both roles are replayed with the vector's ephemeral keys, so every byte
// of every handshake message, transport record and the handshake hash has to match.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync, existsSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import path from 'node:path';
import { NoiseResponder, NoiseInitiator, PROTOCOL_NAME } from '../src/noise.mjs';
import { NoiseFramer } from '../src/frame.mjs';

const here = path.dirname(fileURLToPath(import.meta.url));
const hex = (s) => Buffer.from(s, 'hex');
const NONE = Buffer.alloc(0);

// Replay a vector as the responder (Home Assistant's peer, the role the library plays) and as
// the initiator (the test helper's role).
function replay(v) {
  assert.equal(v.protocol_name, PROTOCOL_NAME);
  const [m0, m1, ...transport] = v.messages;
  const r = new NoiseResponder(hex(v.resp_psks[0]), hex(v.resp_prologue), { ephemeral: hex(v.resp_ephemeral) });
  const i = new NoiseInitiator(hex(v.init_psks[0]), hex(v.init_prologue), { ephemeral: hex(v.init_ephemeral) });

  assert.equal(i.writeMessage(hex(m0.payload)).toString('hex'), m0.ciphertext, 'initiator message 1');
  assert.equal(r.readMessage(hex(m0.ciphertext)).toString('hex'), m0.payload, 'responder reads message 1');
  assert.equal(r.writeMessage(hex(m1.payload)).toString('hex'), m1.ciphertext, 'responder message 2');
  assert.equal(i.readMessage(hex(m1.ciphertext)).toString('hex'), m1.payload, 'initiator reads message 2');

  const rs = r.split(), is = i.split();
  assert.equal(rs.handshakeHash.toString('hex'), v.handshake_hash, 'handshake hash');
  assert.equal(is.handshakeHash.toString('hex'), v.handshake_hash);
  transport.forEach((m, n) => {
    // Interactive pattern: the initiator sends first, then the two alternate.
    const [send, recv] = n % 2 === 0 ? [is.send, rs.recv] : [rs.send, is.recv];
    assert.equal(send.encrypt(NONE, hex(m.payload)).toString('hex'), m.ciphertext, `transport ${n}`);
    assert.equal(recv.decrypt(NONE, hex(m.ciphertext)).toString('hex'), m.payload, `transport ${n} decrypts`);
  });
}

test('noise: the published cacophony vector for Noise_NNpsk0_25519_ChaChaPoly_SHA256', () => {
  const { vectors } = JSON.parse(readFileSync(path.join(here, 'vectors', 'cacophony-nnpsk0.json'), 'utf8'));
  assert.equal(vectors.length, 1);
  for (const v of vectors) replay(v);
});

const python = path.join(here, '..', '.venv', 'bin', 'python');
test('noise: random transcripts from the Python noise library replay byte for byte', { skip: !existsSync(python) && 'needs .venv with aioesphomeapi (brings noiseprotocol)' }, () => {
  const count = Number(process.env.NOISE_VECTORS || 200);
  const seed = Number(process.env.NOISE_SEED || Date.now() % 1e9);
  const { vectors } = JSON.parse(execFileSync(python, ['-I', path.join(here, 'noise_vectors.py'), String(count), String(seed)], { maxBuffer: 64 << 20 }).toString());
  assert.equal(vectors.length, count);
  vectors.forEach((v, n) => { try { replay(v); } catch (err) { err.message += ` (vector ${n}, seed ${seed})`; throw err; } });
});

test('noise: tampering with any byte of the first handshake message fails the MAC', () => {
  const { vectors: [v] } = JSON.parse(readFileSync(path.join(here, 'vectors', 'cacophony-nnpsk0.json'), 'utf8'));
  const msg = hex(v.messages[0].ciphertext);
  for (let at = 0; at < msg.length; at++) {
    const bad = Buffer.from(msg); bad[at] ^= 0x01;
    const r = new NoiseResponder(hex(v.resp_psks[0]), hex(v.resp_prologue));
    assert.throws(() => r.readMessage(bad), (e) => e.code === 'MAC', `byte ${at}`);
  }
  const wrongPrologue = new NoiseResponder(hex(v.resp_psks[0]), Buffer.from('not the prologue'));
  assert.throws(() => wrongPrologue.readMessage(msg), (e) => e.code === 'MAC');
});

test('noise: a low-order ephemeral key from the client is a clean handshake rejection', () => {
  const psk = Buffer.alloc(32, 5);
  for (const low of ['00'.repeat(32), '01' + '00'.repeat(31), 'e0eb7a7c3b41b8ae1656e3faf19fc46ada098deb9c32b1fd866205165f49b800']) {
    const framer = new NoiseFramer({ psk, name: 'n', mac: '000000000000' });
    framer.feed(Buffer.from([1, 0, 0]), () => {});
    // A client holding the psk but sending a low-order point: the MAC passes, the DH must not.
    const s = new NoiseResponder(psk, Buffer.from('NoiseAPIInit\0\0'));
    s.mixKeyAndHash(psk); s.mixHash(hex(low)); s.mixKey(hex(low));
    const body = Buffer.concat([Buffer.from([0]), hex(low), s.encryptAndHash(NONE)]);
    const frame = Buffer.concat([Buffer.from([1, body.length >> 8, body.length & 255]), body]);
    const sent = [];
    assert.throws(() => framer.feed(frame, (b) => sent.push(b)), (e) => e.reject === 'Handshake error', low.slice(0, 8));
    assert.equal(sent.length, 0, 'no handshake reply is sent');
  }
});

test('noise: transport nonces never repeat and a replayed record is refused', () => {
  const psk = Buffer.alloc(32, 9), pro = Buffer.from('p');
  const i = new NoiseInitiator(psk, pro), r = new NoiseResponder(psk, pro);
  r.readMessage(i.writeMessage()); i.readMessage(r.writeMessage());
  const is = i.split(), rs = r.split();
  const same = Buffer.from('same plaintext');
  const a = is.send.encrypt(NONE, same), b = is.send.encrypt(NONE, same);
  assert.notDeepEqual(a, b, 'same plaintext, different ciphertext');
  assert.deepEqual(rs.recv.decrypt(NONE, a), same);
  assert.throws(() => rs.recv.decrypt(NONE, a), 'replay of record 0 refused');
  assert.deepEqual(rs.recv.decrypt(NONE, b), same, 'a failed decrypt does not advance the counter');
  assert.throws(() => rs.send.decrypt(NONE, is.send.encrypt(NONE, same)), 'directions use different keys');
});
